def scan_until_4(r, c, grid, dr, dc):
    """Scan from (r,c) in direction (dr,dc) until a 4 or edge, return distance"""
    rows = len(grid)
    cols = len(grid[0])
    count = 0
    while True:
        tr, tc = r + dr*count, c + dc*count
        if tr < 0 or tr >= rows or tc < 0 or tc >= cols:
            return count  # hit edge
        if grid[tr][tc] == 4:
            return count  # hit 4
        count += 1

def has_horiz_4(r, c, grid):
    """Check if there's a 4 immediately left or right"""
    rows = len(grid)
    cols = len(grid[0])
    return (c > 0 and grid[r][c-1] == 4) or (c < cols-1 and grid[r][c+1] == 4)

def has_vert_4(r, c, grid):
    """Check if there's a 4 immediately up or down"""
    rows = len(grid)
    cols = len(grid[0])
    return (r > 0 and grid[r-1][c] == 4) or (r < rows-1 and grid[r+1][c] == 4)

